public sealed class BookingDb(DbContextOptions<BookingDb> options):DbContext(options){public DbSet<Tenant> Tenants=>Set<Tenant>();public DbSet<Member> Members=>Set<Member>();public DbSet<Branch> Branches=>Set<Branch>();public DbSet<Employee> Employees=>Set<Employee>();public DbSet<Service> Services=>Set<Service>();public DbSet<Shift> Shifts=>Set<Shift>();public DbSet<Leave> Leaves=>Set<Leave>();public DbSet<Customer> Customers=>Set<Customer>();public DbSet<Appointment> Appointments=>Set<Appointment>();protected override void OnModelCreating(ModelBuilder b){b.Entity<Tenant>().HasIndex(x=>x.Slug).IsUnique();b.Entity<Member>().HasIndex(x=>x.Email).IsUnique();b.Entity<Customer>().HasIndex(x=>new{x.TenantId,x.TelegramId}).IsUnique();b.Entity<Appointment>().HasIndex(x=>new{x.TenantId,x.EmployeeId,x.Starts});foreach(var entity in new[]{typeof(Member),typeof(Branch),typeof(Employee),typeof(Service),typeof(Shift),typeof(Leave),typeof(Customer),typeof(Appointment)})b.Entity(entity).HasOne(typeof(Tenant),null).WithMany().HasForeignKey(nameof(Member.TenantId)).OnDelete(DeleteBehavior.Cascade);b.Entity<Employee>().HasOne<Branch>().WithMany().HasForeignKey(x=>x.BranchId).OnDelete(DeleteBehavior.Restrict);b.Entity<Shift>().HasOne<Employee>().WithMany().HasForeignKey(x=>x.EmployeeId).OnDelete(DeleteBehavior.Cascade);b.Entity<Leave>().HasOne<Employee>().WithMany().HasForeignKey(x=>x.EmployeeId).OnDelete(DeleteBehavior.Cascade);b.Entity<Appointment>().HasOne<Employee>().WithMany().HasForeignKey(x=>x.EmployeeId).OnDelete(DeleteBehavior.Restrict);b.Entity<Appointment>().HasOne<Service>().WithMany().HasForeignKey(x=>x.ServiceId).OnDelete(DeleteBehavior.Restrict);b.Entity<Appointment>().HasOne<Customer>().WithMany().HasForeignKey(x=>x.CustomerId).OnDelete(DeleteBehavior.Restrict);b.Entity<Service>().Property(x=>x.Price).HasPrecision(14,2);b.Entity<Appointment>().Property(x=>x.Price).HasPrecision(14,2);}}
